# Build expected cleanly and print compact JSON for a retry with the adjacent pair left unchanged.
expected=copy.deepcopy(g)
segments=[('h',3,6,7,4),('h',3,13,19,8),('v',22,6,7,9),('h',10,13,19,4),('h',10,6,7,7),('v',3,13,14,6),('h',17,6,7,9),('h',17,13,14,4),('v',22,20,20,3)]
for typ,a,b,c,col in segments:
 if typ=='h':
  for x in range(b,c+1): expected[a][x]=col
 else:
  for x in range(b,c+1): expected[x][a]=col
print(json.dumps({'action':'submit','grid':expected},separators=(',',':')))

